net.coobird.thumbnailator.makers.ThumbnailMaker maker = new net.coobird.thumbnailator.makers.ThumbnailMaker() {
    @Override
    public java.awt.image.BufferedImage make(java.awt.image.BufferedImage img) {
        // Provide a concrete implementation for the abstract make method
        int targetWidth = Math.max(1, img.getWidth() / 2);
        int targetHeight = Math.max(1, img.getHeight() / 2);
        return new java.awt.image.BufferedImage(targetWidth, targetHeight, java.awt.image.BufferedImage.TYPE_INT_ARGB);
    }
};

java.awt.image.BufferedImage result = maker.make(sourceImage);

int expectedWidth = Math.max(1, sourceImage.getWidth() / 2);
int expectedHeight = Math.max(1, sourceImage.getHeight() / 2);

assert result != null : "Resulting image should not be null";
assert result.getWidth() == expectedWidth : "Image width should match the implemented logic";
assert result.getHeight() == expectedHeight : "Image height should match the implemented logic";

System.out.println("__CHECK__ ThumbnailMaker " + result.getWidth() + "x" + result.getHeight());

